import {bootstrap,rpc,fileUrl,identity,disposeShim} from './host-shim.js';
const moduleName=new URLSearchParams(location.search).get('module')||'media',titles={media:'媒体处理',pipeline:'任务流水线',world:'3D 场景',production:'画布模板与自动任务'},$=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let world,timer,boot,disposed=false;
function result(value,error=false){const target=$('#result');target.replaceChildren();target.toggleAttribute('data-error',error);if(typeof value==='string'){target.textContent=value;return;}const statusNames={queued:'已加入本机任务',running:'正在本机处理',succeeded:'本机处理完成',completed:'已完成',failed:'处理失败',cancelled:'已停止',interrupted:'任务已中断'};const text=value?.path?'已保存：'+(value.fileName||value.name||value.path.split('/').pop()):value?.loaded?'已打开 '+value.loaded+'（'+value.objects+' 个物体）':value?.status?(statusNames[value.status]||'任务状态：'+value.status):value?.name?'已保存：'+value.name:'操作完成';const label=document.createElement('p');label.textContent=text;const details=document.createElement('details'),summary=document.createElement('summary'),pre=document.createElement('pre');summary.textContent='查看详细信息';pre.dataset.resultJson='true';pre.textContent=JSON.stringify(value,null,2);details.append(summary,pre);target.append(label,details);}

function on(id,fn){$('#'+id)?.addEventListener('click',async event=>{const b=event.currentTarget;b.disabled=true;try{await fn();}catch(error){result(error.message,true);}finally{if(b.isConnected)b.disabled=false;}});}
const input=(id,label,type='text',value='')=>`<label for="${id}">${label}</label><input id="${id}" type="${type}" value="${esc(value)}">`;
const kinds={probe:'查看媒体信息',video_analyze:'采样画面与镜头检测',thumbnail:'提取视频缩略图',video_trim:'视频裁剪',video_convert:'视频转码',audio_extract:'提取音轨',audio_trim:'音频裁剪',audio_merge:'音频顺序合并',image_transform:'图片裁剪与变换',image_montage:'图片拼图'};
async function assetPicker(){const assets=await rpc('aiyouplus_local_assets');return`<label for="asset">从统一素材库选择</label><select id="asset"><option value="">选择素材</option>${assets.map(a=>`<option value="${esc(a.path)}">${esc(a.name)} · ${esc(a.kind)}</option>`).join('')}</select>`;}
async function publish(output){if(output?.path){const imported=await rpc('aiyouplus_local_import',{inputPaths:[output.path]});result({...output,unifiedAssetId:imported[0]?.id});const link=document.createElement('a');link.href=fileUrl(output.path);link.textContent='打开本地结果';link.target='_blank';link.rel='noopener';$('#result').append('\n',link);}else result(output);}
async function renderMedia(){const h=$('#content');h.innerHTML=await assetPicker()+`<label for="operation">处理方式</label><select id="operation">${Object.entries(kinds).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select>`+'<details><summary>手动输入本机路径</summary>'+input('source','输入素材原件路径')+'</details>'+`<label for="sources">更多输入（合并音频或拼图，每行一个）</label><textarea id="sources"></textarea><div class="row">`+input('start','开始秒数','number','0')+input('duration','时长秒数（可空）','number')+input('width','宽度（可空）','number')+input('height','高度（可空）','number')+'</div><div class="row">'+input('rotation','顺时针旋转','number','0')+input('columns','拼图列数','number','2')+'</div><button id="run">执行本地处理</button>';$('#asset').onchange=()=>$('#source').value=$('#asset').value;on('run',async()=>{const operation=$('#operation').value,args={inputPath:$('#source').value};for(const [id,key]of [['start','startSeconds'],['duration','durationSeconds'],['width','width'],['height','height'],['rotation','rotation'],['columns','columns']])if($('#'+id).value!=='')args[key]=Number($('#'+id).value);if(['audio_merge','image_montage'].includes(operation))args.inputPaths=[$('#source').value,...$('#sources').value.split('\n')].map(x=>x.trim()).filter(Boolean);result('正在处理…');await publish(await rpc('aiyouplus_media_'+operation,args));});}
async function renderPipeline(){const h=$('#content');h.innerHTML=await assetPicker()+'<details><summary>手动输入本机路径</summary>'+input('source','输入素材原件路径')+'</details>'+'<label for="flow">流程</label><select id="flow"><option value="video">视频裁剪 → 提取音轨</option><option value="image">图片缩放 → 旋转</option></select>'+input('name','任务名称','text','本地处理流程')+'<button id="run">开始任务</button><div id="jobs"></div>';$('#asset').onchange=()=>$('#source').value=$('#asset').value;on('run',async()=>{const base=boot.exportsDirectory+'/flow-'+crypto.randomUUID(),source=$('#source').value,steps=$('#flow').value==='image'?[{command:'aiyouplus_media_image_transform',args:{inputPath:source,outputPath:base+'-scaled.png',width:512}},{command:'aiyouplus_media_image_transform',args:{inputPath:'$previous',outputPath:base+'-rotated.png',rotation:90}}]:[{command:'aiyouplus_media_video_trim',args:{inputPath:source,outputPath:base+'.mp4',startSeconds:0,durationSeconds:2}},{command:'aiyouplus_media_audio_extract',args:{inputPath:'$previous',outputPath:base+'.wav'}}];result(await rpc('aiyouplus_local_pipeline_run',{name:$('#name').value,steps}));await jobs();});await jobs();timer=setInterval(()=>void jobs().catch(error=>result(error.message,true)),1200);}
async function jobs(){if(disposed)return;const list=await rpc('aiyouplus_local_jobs');$('#jobs').innerHTML=list.map(job=>`<article><strong>${esc(job.name)}</strong><p>${esc(job.status)} · ${job.completed}/${job.steps.length}</p>${job.error?`<p>${esc(job.error)}</p>`:''}${['running','queued'].includes(job.status)?`<button data-cancel="${esc(job.id)}">停止本机任务</button>`:['failed','cancelled','interrupted'].includes(job.status)?`<button data-resume="${esc(job.id)}">从检查点继续</button>`:''}${job.results.filter(r=>r.path).map(r=>`<button data-result="${esc(r.path)}">结果入统一库</button>`).join('')}</article>`).join('');for(const b of document.querySelectorAll('[data-cancel]'))b.onclick=()=>rpc('aiyouplus_local_pipeline_cancel',{id:b.dataset.cancel}).then(jobs).catch(e=>result(e.message,true));for(const b of document.querySelectorAll('[data-resume]'))b.onclick=()=>rpc('aiyouplus_local_pipeline_run',{resumeId:b.dataset.resume}).then(jobs).catch(e=>result(e.message,true));for(const b of document.querySelectorAll('[data-result]'))b.onclick=()=>publish({path:b.dataset.result});}
async function renderWorld(){const h=$('#content');h.innerHTML='<div class="row">'+['box','sphere','cylinder','plane'].map(s=>`<button data-shape="${s}">${({box:'方块',sphere:'球体',cylinder:'圆柱',cone:'圆锥',torus:'圆环',plane:'平面'})[s]}</button>`).join('')+'</div><div id="viewport" class="world"></div><div id="lp-world-objects"></div><div class="row">'+['position','rotation','scale'].flatMap(kind=>['x','y','z'].map(axis=>`<label>${({position:'位置',rotation:'角度',scale:'缩放'})[kind]} ${axis}<input type="number" data-transform="${kind}" data-axis="${axis}" value="${kind==='scale'?1:0}"></label>`)).join('')+'</div>'+input('lp-world-color','材质颜色','color','#67c5ad')+input('scene-name','场景名称','text','我的场景')+'<button id="save">保存场景</button><button id="load">打开场景 JSON</button><input id="scene-file" type="file" accept="application/json,.json" hidden><button id="export">导出 GLB</button><button id="remove">删除选中物体</button>';const {createWorld}=await import('./local/world.js');world=createWorld($('#viewport'));for(const b of document.querySelectorAll('[data-shape]'))b.onclick=()=>world.add(b.dataset.shape);for(const e of document.querySelectorAll('[data-transform]'))e.onchange=()=>world.transform(e.dataset.transform,e.dataset.axis,Number(e.value));$('#lp-world-color').oninput=e=>world.color(e.target.value);const savedScene=localStorage.getItem('dsh.world.scenePath');if(savedScene)world.load(JSON.parse(await rpc('aiyouplus_local_read_text',{path:savedScene})));on('save',async()=>{const value=await rpc('aiyouplus_local_scene_save',{name:$('#scene-name').value,scene:world.snapshot()});localStorage.setItem('dsh.world.scenePath',value.path);result(value);});on('load',()=>$('#scene-file').click());$('#scene-file').onchange=async event=>{try{const file=event.target.files[0];if(!file)return;if(!/\.json$/i.test(file.name))throw Error('请选择场景 JSON 文件');const value=world.load(JSON.parse(await file.text()));result({loaded:file.name,objects:value.objects.length});}catch(error){result(error.message,true);}finally{event.target.value='';}};on('export',async()=>{let text='';for(const b of new Uint8Array(world.exportGlb()))text+=String.fromCharCode(b);await publish(await rpc('aiyouplus_local_scene_export',{outputPath:boot.exportsDirectory+'/scene-'+crypto.randomUUID()+'.glb',dataBase64:btoa(text)}));});on('remove',()=>world.removeSelected());}
const production=(method,...args)=>rpc('canvas_production',{method,args});
async function renderProduction(){
 const state=await production('snapshot'),h=$('#content');
 h.innerHTML=input('recipe-name','模板名称','text','我的模板')+input('recipe-goal','目标')+
  '<label for="input-mode">参考输入</label><select id="input-mode"><option value="fixed">固定当前参考</option><option value="each-run">每次接受新素材</option></select>'+input('output-directory','成品目录（限当前项目，可空）')+
  '<h3>选择当前画布的输入与输出</h3>'+state.nodes.map(n=>`<label>${esc(n.name)} · ${esc(n.type)}<select data-role="${esc(n.id)}"><option value="">不作为槽位</option><option value="input">输入</option><option value="output">输出</option></select></label>`).join('')+
  '<button id="save">保存为模板</button><button id="refresh">刷新画布与运行状态</button><label for="import-recipe">导入模板文件</label><input id="import-recipe" type="file" accept="application/json,.json"><h3>已有模板</h3>'+
  state.recipes.map(r=>`<article data-recipe="${esc(r.id)}">${input('name-'+r.id,'名称','text',r.name)}${input('goal-'+r.id,'目标','text',r.goal)}<p>版本 ${esc(r.currentVersion)} · ${r.slots.filter(s=>s.role==='input').length} 个输入 · ${r.slots.filter(s=>s.role==='output').length} 个输出</p><button data-run="${esc(r.id)}">执行模板</button><button data-edit="${esc(r.id)}">保存名称与目标</button><button data-export="${esc(r.id)}">导出模板</button><button data-delete="${esc(r.id)}">删除模板</button></article>`).join('')+
  '<h3>自动任务</h3><label for="trigger-recipe">模板</label><select id="trigger-recipe">'+state.recipes.map(r=>`<option value="${esc(r.id)}">${esc(r.name)}</option>`).join('')+'</select><label for="trigger-kind">触发方式</label><select id="trigger-kind"><option value="schedule">定时</option><option value="watch_folder">项目内文件夹新素材</option></select>'+input('trigger-minutes','间隔分钟','number','5')+input('trigger-folder','监视文件夹（限当前项目）')+'<p>仅在本项目画布打开时执行；模型步骤沿用配置与确认规则。</p><button id="trigger-save">添加自动任务</button>'+state.triggers.items.map(t=>`<article><strong>${esc(state.recipes.find(r=>r.id===t.recipeId)?.name||t.recipeId)}</strong><p>${esc(t.kind==='schedule'?'每 '+t.everyMinutes+' 分钟':t.folderPath)} · ${t.enabled?'已启用':'已暂停'} · ${esc(t.lastError||t.lastRunStatus||'等待触发')}</p><button data-trigger-run="${esc(t.id)}">现在执行一次</button><button data-trigger-toggle="${esc(t.id)}">${t.enabled?'暂停自动任务':'启用自动任务'}</button><button data-trigger-delete="${esc(t.id)}">删除自动任务</button></article>`).join('')+
  '<h3>运行与交付状态</h3><pre>'+esc(JSON.stringify({activeRun:state.activeRun,history:state.history},null,2))+'</pre>'+['pause_run','resume_run','cancel_run','retry_run'].map(action=>`<button data-control="${action}">${({pause_run:'暂停',resume_run:'继续',cancel_run:'停止',retry_run:'重试失败步骤'})[action]}</button>`).join('');
 on('save',async()=>{const roles=Object.fromEntries([...document.querySelectorAll('[data-role]')].filter(e=>e.value).map(e=>[e.dataset.role,e.value]));result(await production('createFromCanvas',{name:$('#recipe-name').value,goal:$('#recipe-goal').value,roles,inputMode:$('#input-mode').value,outputDirectory:$('#output-directory').value.trim()}));await renderProduction();});
 on('refresh',renderProduction);on('trigger-save',async()=>{result(await production('saveTrigger',{kind:$('#trigger-kind').value,recipeId:$('#trigger-recipe').value,everyMinutes:Number($('#trigger-minutes').value),folderPath:$('#trigger-folder').value.trim(),enabled:true}));await renderProduction();});
 $('#import-recipe').onchange=async event=>{try{const file=event.target.files[0];if(file){result(await production('saveRecipe',JSON.parse(await file.text())));await renderProduction();}}catch(error){result(error.message,true);}};
 const bind=(attr,fn)=>{for(const button of document.querySelectorAll('[data-'+attr+']'))button.onclick=async()=>{button.disabled=true;try{await fn(button.getAttribute('data-'+attr));}catch(error){result(error.message,true);}finally{if(button.isConnected)button.disabled=false;}};};
 bind('run',async id=>result(await production('execute',id)));
 bind('edit',async id=>{result(await production('saveRecipe',{...state.recipes.find(r=>r.id===id),name:document.getElementById('name-'+id).value,goal:document.getElementById('goal-'+id).value}));await renderProduction();});
 bind('export',async id=>{const file=boot.exportsDirectory+'/recipe-'+crypto.randomUUID()+'.json';await rpc('write_text_file_atomic',{path:file,body:JSON.stringify(state.recipes.find(r=>r.id===id),null,2)});result({path:file});const link=document.createElement('a');link.href=fileUrl(file);link.download='canvas-template.json';link.textContent='下载模板文件';$('#result').append(link);});
 bind('delete',async id=>{await production('deleteRecipe',id);await renderProduction();});
 bind('control',async action=>{result(await production('control',action,state.activeRun?.id));await renderProduction();});
 bind('trigger-run',async id=>result(await production('runTrigger',id)));
 bind('trigger-toggle',async id=>{const trigger=state.triggers.items.find(t=>t.id===id);await production('saveTrigger',{...trigger,enabled:!trigger.enabled});await renderProduction();});
 bind('trigger-delete',async id=>{await production('deleteTrigger',id);await renderProduction();});
}

try{if(!titles[moduleName])throw Error('未知工具菜单');$('#title').textContent=titles[moduleName];boot=await bootstrap();await({media:renderMedia,pipeline:renderPipeline,world:renderWorld,production:renderProduction}[moduleName])();}catch(error){result(error.message,true);}window.addEventListener('pagehide',()=>{disposed=true;clearInterval(timer);world?.dispose();disposeShim();},{once:true});
